GUARDS_SQL = "CREATE FUNCTION guard_workflow_run() RETURNS trigger\nLANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$\nBEGIN\n IF TG_OP='DELETE' THEN\n   IF public.config_workflow_demo_purge_authorized(OLD.tenant_id) THEN RETURN OLD; END IF;\n   RAISE EXCEPTION 'Workflow run evidence is retained';\n END IF;\n IF TG_OP='INSERT' THEN\n   IF NEW.status<>'queued' OR NEW.next_step<>0 OR NEW.version<>1\n      OR jsonb_typeof(NEW.plan_json->'steps')<>'array'\n      OR jsonb_array_length(NEW.plan_json->'steps') NOT BETWEEN 1 AND 12 THEN\n     RAISE EXCEPTION 'Workflow runs begin as bounded queued plans';\n   END IF;\n   IF NEW.origin_channel='workspace_mcp' AND NOT EXISTS (\n     SELECT 1 FROM workspace_mcp_grants g WHERE g.tenant_id=NEW.tenant_id\n       AND g.id=NEW.grant_id AND g.user_id=NEW.actor_user_id AND g.client_id=NEW.client_id\n   ) THEN RAISE EXCEPTION 'Workflow origin grant must belong to its actor'; END IF;\n   RETURN NEW;\n END IF;\n IF (to_jsonb(NEW)-ARRAY['status','version','next_step','failure_code','updated_at','completed_at'])\n    IS DISTINCT FROM\n    (to_jsonb(OLD)-ARRAY['status','version','next_step','failure_code','updated_at','completed_at']) THEN\n   RAISE EXCEPTION 'Workflow plan identity and source evidence are immutable';\n END IF;\n IF OLD.status IN ('completed','cancelled','failed') AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN\n   RAISE EXCEPTION 'Terminal workflow runs are immutable';\n END IF;\n IF NEW.version < OLD.version OR NEW.version > OLD.version+1\n    OR NEW.next_step < OLD.next_step OR NEW.next_step > OLD.next_step+1 THEN\n   RAISE EXCEPTION 'Workflow checkpoints advance monotonically';\n END IF;\n IF NEW.next_step>OLD.next_step AND NOT EXISTS(\n   SELECT 1 FROM workflow_run_steps s WHERE s.tenant_id=OLD.tenant_id AND s.run_id=OLD.id\n     AND s.position=OLD.next_step AND s.status='completed'\n ) THEN RAISE EXCEPTION 'Only completed steps advance the run'; END IF;\n IF NEW.status='completed' AND (NEW.next_step<>jsonb_array_length(NEW.plan_json->'steps')\n    OR (SELECT count(*) FROM workflow_run_steps s WHERE s.tenant_id=NEW.tenant_id\n        AND s.run_id=NEW.id AND s.status='completed')<>NEW.next_step) THEN\n   RAISE EXCEPTION 'A completed run requires every planned checkpoint';\n END IF;\n RETURN NEW;\nEND $$;\n\nCREATE FUNCTION guard_workflow_run_step() RETURNS trigger\nLANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE run_record record; definition jsonb;\nBEGIN\n IF TG_OP='DELETE' THEN\n   IF public.config_workflow_demo_purge_authorized(OLD.tenant_id) THEN RETURN OLD; END IF;\n   RAISE EXCEPTION 'Workflow step evidence is retained';\n END IF;\n SELECT * INTO run_record FROM workflow_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION 'Workflow step requires its tenant run'; END IF;\n IF TG_OP='INSERT' THEN\n   definition := run_record.plan_json->'steps'->NEW.position;\n   IF definition IS NULL OR definition->>'step_key' IS DISTINCT FROM NEW.step_key\n      OR definition->>'capability' IS DISTINCT FROM NEW.capability\n      OR definition->'references' IS DISTINCT FROM NEW.references_json\n      OR definition->>'arguments_sha256' IS DISTINCT FROM NEW.arguments_sha256\n      OR NEW.status<>'pending' OR NEW.attempts<>0 THEN\n     RAISE EXCEPTION 'Workflow steps must match the immutable plan';\n   END IF;\n   RETURN NEW;\n END IF;\n IF (NEW.id,NEW.tenant_id,NEW.run_id,NEW.position,NEW.step_key,NEW.capability,NEW.references_json,NEW.created_at)\n    IS DISTINCT FROM\n    (OLD.id,OLD.tenant_id,OLD.run_id,OLD.position,OLD.step_key,OLD.capability,OLD.references_json,OLD.created_at) THEN\n   RAISE EXCEPTION 'Workflow step identity is immutable';\n END IF;\n IF OLD.status='completed' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN\n   RAISE EXCEPTION 'Completed workflow step evidence is immutable';\n END IF;\n IF (NEW.arguments_ciphertext,NEW.arguments_sha256) IS DISTINCT FROM (OLD.arguments_ciphertext,OLD.arguments_sha256)\n    AND NOT (OLD.status='awaiting_input' AND NEW.status='pending' AND OLD.result_ciphertext IS NULL) THEN\n   RAISE EXCEPTION 'Only a missing-input pause may accept additional arguments';\n END IF;\n IF OLD.result_ciphertext IS NOT NULL AND\n    (NEW.result_ciphertext,NEW.result_sha256,NEW.result_summary,NEW.task_id,NEW.artifact_id,NEW.artifact_revision_id,NEW.action_sha256)\n    IS DISTINCT FROM\n    (OLD.result_ciphertext,OLD.result_sha256,OLD.result_summary,OLD.task_id,OLD.artifact_id,OLD.artifact_revision_id,OLD.action_sha256) THEN\n   RAISE EXCEPTION 'Completed capability result and review binding are immutable';\n END IF;\n IF NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 THEN\n   RAISE EXCEPTION 'Workflow attempt counter must advance once';\n END IF;\n IF NEW.status='completed' THEN\n   IF NEW.result_ciphertext IS NULL OR NEW.result_sha256 IS NULL THEN\n     RAISE EXCEPTION 'Completed steps require durable result evidence';\n   END IF;\n   IF NEW.capability IN ('propose_matter_document','propose_document_from_template') AND NEW.approval_id IS NULL THEN\n     RAISE EXCEPTION 'Completed document steps require exact attorney approval';\n   END IF;\n   IF NEW.capability IN ('propose_client_email','propose_client_sms') AND NOT EXISTS (\n     SELECT 1 FROM task_automation_runs a WHERE a.tenant_id=NEW.tenant_id AND a.task_id=NEW.task_id\n       AND a.action_sha256=NEW.action_sha256 AND a.status='sent' AND a.delivery_certainty_v2='confirmed_sent'\n   ) THEN RAISE EXCEPTION 'Completed delivery steps require confirmed delivery evidence'; END IF;\n END IF;\n IF NEW.task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tasks t WHERE t.tenant_id=NEW.tenant_id\n       AND t.id=NEW.task_id AND t.matter_id=run_record.matter_id) THEN\n   RAISE EXCEPTION 'Workflow review task must belong to its matter';\n END IF;\n IF NEW.artifact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM generated_artifacts a WHERE a.tenant_id=NEW.tenant_id\n       AND a.id=NEW.artifact_id AND a.matter_id=run_record.matter_id AND a.task_id=NEW.task_id) THEN\n   RAISE EXCEPTION 'Workflow artifact must belong to its matter and review task';\n END IF;\n RETURN NEW;\nEND $$;\n\nCREATE FUNCTION guard_workflow_run_event() RETURNS trigger\nLANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$\nBEGIN\n IF TG_OP='DELETE' AND public.config_workflow_demo_purge_authorized(OLD.tenant_id) THEN RETURN OLD; END IF;\n IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Workflow events are immutable'; END IF;\n IF NEW.step_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workflow_run_steps s\n    WHERE s.tenant_id=NEW.tenant_id AND s.id=NEW.step_id AND s.run_id=NEW.run_id) THEN\n    RAISE EXCEPTION 'Workflow event step must belong to its run';\n END IF;\n IF jsonb_typeof(NEW.metadata_json)<>'object' OR pg_column_size(NEW.metadata_json)>4096 THEN\n    RAISE EXCEPTION 'Workflow event metadata must remain bounded';\n END IF;\n RETURN NEW;\nEND $$;\n"

